function focus(field:string){const input=root()?.querySelector<HTMLInputElement>(`[data-cut-field="${field}"]`);input?.focus({preventScroll:true});input?.scrollIntoView({block:'nearest',inline:'nearest'})}
function focusView(){if(busy())return;if(nextWorkFocus&&work()&&query().get('roll')){const field=nextWorkFocus;nextWorkFocus='';focus(field);return}if(session.signedOut||!session.account)focus('loginAccount');else if(route().tab==='receive'||!route().id)focus('scan');else if(work()&&query().get('roll'))focus('work-rollNo');else if(movement())focus('movementQty');else if(editOpen.has(scope()))focus('remaining');else root()?.querySelector<HTMLButtonElement>('footer button:not(:disabled)')?.focus()}
