export function closeCentralCuttingOverlay(){const panel=root()?.querySelector('[data-central-overlay]');if(!panel)return false;panel.remove();focusView();return true}
function dirty(){return [...receiveDrafts].some(([key,d])=>{const node=d.pending?.pickupNodeId,known=node&&recoveries.has(key.slice(0,-node.length)+'receive|'+node);return !known&&!!(d.ids.length||d.pending)})||[...adjustDrafts.keys()].some(key=>!recoveries.has(key))||[...movementDrafts.keys()].some(key=>!recoveries.has(key))||[...workDrafts.keys()].some(key=>!recoveries.has(key))||[...handoutRequests.keys()].some(key=>!recoveries.has(key))||[...handoutReplacements].some(([key,ids])=>ids.length&&!recoveries.has(key))}
registerCentralDraftDiscard(()=>{epoch++;receiveDrafts.clear();adjustDrafts.clear();movementDrafts.clear();workDrafts.clear();workWaste.clear();workPhysical.clear();workScans.clear();nextWorkFocus='';workSource=undefined;handoutSource=undefined;handoutRequests.clear();handoutRecordViews.clear();handoutReplacements.clear();handoutLastSheets.clear();notices.clear();editOpen.clear();recoveries.clear();warehouseStates.clear();receiveWarehouses.clear();scan='';logoutScope='';login={account:'',password:''}},dirty)
